import React from 'react'

function ReviewsSection() {
    return (
        <div className="reviews w-full min-h-[510px] flex justify-center items-start py-10">
            <div className="w-[90%] min-h-[450px] bg-gray-100 rounded-lg p-6">
                <div className="w-full min-h-[80px] grid grid-cols-2 gap-4">
                    <div className="bg-orange-100 p-4 rounded-lg">Отзыв 1</div>
                    <div className="bg-lime-100 p-4 rounded-lg">Отзыв 2</div>
                </div>
            </div>
        </div>
    )
}

export default ReviewsSection;
